export default YourFriendsPage;

import React, { createContext, useContext, useState, useEffect, ReactNode, useCallback } from 'react';
import { Session, User as SupabaseUser } from '@supabase/supabase-js';
import { supabase } from '../services/supabaseClient';
import { User, UserRole, ThemePreference } from '../types';
import { getErrorMessage } from '../utils';

interface AuthContextType {
    user: User | null;
    session: Session | null;
    loadingInitial: boolean;
    loading: boolean;
    error: string | null;
    signIn: (credentials: { email: string; password: string }) => Promise<void>;
    signUp: (credentials: { email: string; password: string; role: UserRole; fullName: string; course: string }) => Promise<void>;
    signOut: () => Promise<void>;
    updateUserProfile: (updates: Partial<User>) => void;
    updateUserAvatar: (file: File) => Promise<void>;
    removeUserAvatar: () => Promise<void>;
    ensureProfile: () => Promise<void>;
    clearError: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [user, setUser] = useState<User | null>(null);
    const [session, setSession] = useState<Session | null>(null);
    const [loadingInitial, setLoadingInitial] = useState(true);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    // Helper to construct user from session data alone (Offline/Fallback mode)
    const createFallbackUser = (authUser: SupabaseUser): User => {
        const metadata = authUser.user_metadata || {};
        return {
            id: authUser.id,
            email: authUser.email || '',
            role: (metadata.role as UserRole) || UserRole.STUDENT,
            full_name: metadata.full_name || authUser.email?.split('@')[0] || 'User',
            course: metadata.course,
            preferred_theme: (metadata.preferred_theme as ThemePreference) || ThemePreference.SYSTEM,
            avatar_url: metadata.avatar_url
        };
    };

    // New method: Explicitly ensure profile exists in DB.
    // Call this before performing actions that require FK constraints (like creating decks/subjects).
    const ensureProfile = useCallback(async (): Promise<void> => {
        if (!user) return;

        try {
            // 1. Check if profile exists (fast check)
            const { data, error: selectError } = await supabase
                .from('profiles')
                .select('id')
                .eq('id', user.id)
                .single();

            if (!selectError && data) return; // Exists, we are good.

            console.log("Profile missing during check. Attempting JIT creation...");

            // 2. If not, upsert (Self-Healing)
            const newProfile = {
                id: user.id,
                email: user.email,
                full_name: user.full_name,
                role: user.role,
                course: user.course || null,
                preferred_theme: user.preferred_theme,
                avatar_url: user.avatar_url || null
            };

            const { error: insertError } = await supabase.from('profiles').upsert(newProfile);

            if (insertError) {
                 console.error("ensureProfile failed:", insertError);
            }
        } catch (err) {
            console.error("Error in ensureProfile:", err);
        }
    }, [user]);

    // Helper to get or create profile (Self-Healing)
    const getOrCreateProfile = async (authUser: SupabaseUser): Promise<User | null> => {
        try {
            // 1. Try to fetch existing profile
            const { data: profile, error: fetchError } = await supabase
                .from('profiles')
                .select('*')
                .eq('id', authUser.id)
                .single();

            if (!fetchError && profile) {
                return profile as User;
            }

            // 2. If missing, try to create it (Self-Healing)
            console.warn("User profile missing/unreachable. Attempting to auto-repair...", fetchError?.message);

            const metadata = authUser.user_metadata || {};
            const newProfile = {
                id: authUser.id,
                email: authUser.email,
                full_name: metadata.full_name || authUser.email?.split('@')[0] || 'Unknown User',
                role: metadata.role || UserRole.STUDENT,
                course: metadata.course || null,
                preferred_theme: ThemePreference.SYSTEM,
                avatar_url: metadata.avatar_url || null
            };

            const { data: insertedProfile, error: insertError } = await supabase
                .from('profiles')
                .insert(newProfile)
                .select()
                .single();

            if (insertError) {
                console.error("Failed to auto-repair profile:", insertError);
                return createFallbackUser(authUser);
            }

            return insertedProfile as User;

        } catch (err) {
            console.error("Error in getOrCreateProfile:", err);
            return createFallbackUser(authUser);
        }
    };

    useEffect(() => {
        let mounted = true;

        const initializeAuth = async () => {
            // Set a failsafe timeout to clear loading state even if everything else hangs
            // This prevents infinite loading screens
            const globalTimeout = setTimeout(() => {
                if (mounted && loadingInitial) {
                    console.warn("Auth initialization timed out globally. Forcing load complete.");
                    setLoadingInitial(false);
                }
            }, 5000); 

            try {
                // 1. Get Session
                const { data, error } = await supabase.auth.getSession();
                if (error) {
                    console.warn("Error restoring session:", error.message);
                    // Handle "Refresh Token Not Found" or other refresh token errors
                    if (error.message.includes("Refresh Token Not Found") || error.message.includes("Invalid Refresh Token")) {
                        console.warn("Refresh token invalid. Clearing session to force re-login.");
                        await supabase.auth.signOut();
                        if (mounted) {
                            setUser(null);
                            setSession(null);
                        }
                    }
                }

                const initialSession = data?.session;
                if(mounted) setSession(initialSession);

                if (initialSession?.user) {
                    // 2. Get Profile with strict Timeout
                    // Create a promise that rejects after 4 seconds to prevent hanging
                    const profilePromise = getOrCreateProfile(initialSession.user);
                    const timeoutPromise = new Promise<User | null>((resolve) => 
                        setTimeout(() => resolve(null), 3000)
                    );

                    try {
                        // Race the profile fetch against the timeout
                        const profile = await Promise.race([
                            profilePromise,
                            timeoutPromise
                        ]);

                        if (mounted) {
                            setUser(profile || createFallbackUser(initialSession.user));
                        }
                    } catch (err) {
                        console.warn("Profile fetch timed out or failed, using fallback.", err);
                        // If DB is slow/down, simply use the session data to log them in
                        if (mounted) setUser(createFallbackUser(initialSession.user));
                    }
                } else {
                    if (mounted) setUser(null);
                }
            } catch (err) {
                console.error("Auth init failed:", err);
            } finally {
                clearTimeout(globalTimeout);
                if (mounted) setLoadingInitial(false);
            }
        };

        initializeAuth();

        const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event, session) => {
            if (!mounted) return;

            // Update session state immediately
            setSession(session);

            if (event === 'SIGNED_OUT') {
                setUser(null);
                setLoadingInitial(false);
            } else if (event === 'SIGNED_IN' || event === 'TOKEN_REFRESHED' || event === 'INITIAL_SESSION') {
                if (session?.user) {
                    // If we don't have a user yet, or if the ID changed, fetch profile
                    if (!user || user.id !== session.user.id) {
                         // Use fallback immediately if loading is taking too long
                         getOrCreateProfile(session.user).then(profile => {
                             if (!mounted) return;
                             setUser(profile || createFallbackUser(session.user));
                             setLoadingInitial(false);
                         }).catch(() => {
                             if(mounted) {
                                 setUser(createFallbackUser(session.user));
                                 setLoadingInitial(false);
                             }
                         });
                    }
                } else {
                    setLoadingInitial(false);
                }
            }
        });

        return () => {
            mounted = false;
            subscription.unsubscribe();
        };
    }, []);

    const signIn = async (credentials: { email: string; password: string }) => {
        setLoading(true);
        setError(null);
        try {
            const { error, data } = await supabase.auth.signInWithPassword(credentials);
            if (error) throw error;

            if (data.user) {
                const profile = await getOrCreateProfile(data.user);
                setUser(profile || createFallbackUser(data.user));
            }
        } catch (e: any) {
            setError(getErrorMessage(e));
            throw e;
        } finally {
            setLoading(false);
        }
    };

    const signUp = async (credentials: { email: string; password: string; role: UserRole; fullName: string; course: string }) => {
        setLoading(true);
        setError(null);
        try {
            const { data, error } = await supabase.auth.signUp({
                email: credentials.email,
                password: credentials.password,
                options: {
                    data: {
                        full_name: credentials.fullName,
                        role: credentials.role,
                        course: credentials.course,
                        preferred_theme: ThemePreference.SYSTEM,
                    }
                }
            });

            if (error) throw error;
            if (!data.user) throw new Error("Sign up successful, but no user data returned.");

            if (data.user && !data.session) {
                throw new Error("ACCOUNT_CREATED_CHECK_EMAIL");
            }

            const profile = await getOrCreateProfile(data.user);
            setUser(profile || createFallbackUser(data.user));

        } catch (e: any) {
            const msg = getErrorMessage(e);
            if (e.message === "ACCOUNT_CREATED_CHECK_EMAIL") {
                setError("ACCOUNT_CREATED_CHECK_EMAIL");
            } else {
                setError(msg);
            }
            if (e.message !== "ACCOUNT_CREATED_CHECK_EMAIL") {
                 throw e;
            }
        } finally {
            setLoading(false);
        }
    };

    const signOut = async () => {
        setLoading(true);
        setError(null);
        try {
            const { error } = await supabase.auth.signOut();
            // If signOut fails (e.g., refresh token issue), we still want to clear local state.
            // We log the error but proceed to clear the user.
            if (error) console.error("Sign out error (proceeding to clear state):", error);

            setUser(null);
            setSession(null);
        } catch(e: any) {
            setError(getErrorMessage(e));
            // Even if exception, force clear.
            setUser(null);
            setSession(null);
        } finally {
            setLoading(false);
        }
    };

    const updateUserProfile = (updates: Partial<User>) => {
        if (user) {
            setUser({ ...user, ...updates });
        }
    };

    const updateUserAvatar = async (file: File) => {
        if (!user) throw new Error("User not logged in.");
        const filePath = `${user.id}/${Date.now()}_${file.name}`;

        const { error: uploadError } = await supabase.storage
            .from('avatars')
            .upload(filePath, file, { upsert: true });

        if (uploadError) throw uploadError;

        const { data } = supabase.storage.from('avatars').getPublicUrl(filePath);
        const newAvatarUrl = `${data.publicUrl}?t=${new Date().getTime()}`;

        const { error: updateError } = await supabase
            .from('profiles')
            .update({ avatar_url: newAvatarUrl })
            .eq('id', user.id);

        if (updateError) throw updateError;

        setUser({ ...user, avatar_url: newAvatarUrl });
    };

    const removeUserAvatar = async () => {
        if (!user || !user.avatar_url) return;

        const { error: updateError } = await supabase
            .from('profiles')
            .update({ avatar_url: null })
            .eq('id', user.id);

        if (updateError) throw updateError;

        setUser({ ...user, avatar_url: undefined });
    };

    const value: AuthContextType = {
        user,
        session,
        loadingInitial,
        loading,
        error,
        signIn,
        signUp,
        signOut,
        updateUserProfile,
        updateUserAvatar,
        removeUserAvatar,
        ensureProfile,
        clearError: () => setError(null),
    };

    return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => {
    const context = useContext(AuthContext);
    if (context === undefined) {
        throw new Error('useAuth must be used within an AuthProvider');
    }
    return context;
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { UserRole, ThemePreference } from '../types';
import { supabase } from '../services/supabaseClient';
import { getErrorMessage } from '../utils';
import { SunIcon, MoonIcon, ProfileAvatar, TrashIcon } from './icons';
import { useAuth } from './AuthProvider';

const SettingsPage: React.FC = () => {
    const { user, updateUserProfile, updateUserAvatar, removeUserAvatar } = useAuth();

    // Profile State
    const [fullName, setFullName] = useState(user?.full_name || '');
    const [course, setCourse] = useState(user?.course || '');
    const [isSaving, setIsSaving] = useState(false);
    const [saveSuccess, setSaveSuccess] = useState<string | null>(null);
    const [saveError, setSaveError] = useState<string | null>(null);

    // Avatar State
    const [isUploading, setIsUploading] = useState(false);
    const [avatarError, setAvatarError] = useState<string | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if(user) {
            setFullName(user.full_name);
            setCourse(user.course || '');
        }
    }, [user]);

    const effectiveTheme = useMemo(() => {
        if (!user || user.preferred_theme === 'system') {
            return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
        }
        return user.preferred_theme;
    }, [user?.preferred_theme]);

    const handleThemeChange = async (newTheme: ThemePreference) => {
        if (!user) return;
        try {
            const { error } = await supabase
                .from('profiles')
                .update({ preferred_theme: newTheme })
                .eq('id', user.id);
            if (error) throw error;
            updateUserProfile({ preferred_theme: newTheme });
        } catch (err) {
            // Handle theme update error if necessary
            console.error("Failed to update theme", getErrorMessage(err));
        }
    };

    const handleProfileSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!user) return;

        setIsSaving(true);
        setSaveSuccess(null);
        setSaveError(null);

        const updates: { full_name: string; course?: string } = {
            full_name: fullName,
        };
        if (user.role === UserRole.STUDENT) {
            updates.course = course;
        }

        try {
            const { error } = await supabase
                .from('profiles')
                .update(updates)
                .eq('id', user.id);

            if (error) throw error;

            updateUserProfile(updates);
            setSaveSuccess('Profile updated successfully!');
            setTimeout(() => setSaveSuccess(null), 3000);
        } catch (err) {
            setSaveError(`Failed to update profile: ${getErrorMessage(err)}`);
        } finally {
            setIsSaving(false);
        }
    };

    const handleFileChange = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (!file) return;

        if (file.size > 2 * 1024 * 1024) { // 2MB limit
            setAvatarError("Image must be smaller than 2MB.");
            return;
        }

        setIsUploading(true);
        setAvatarError(null);
        try {
            await updateUserAvatar(file);
        } catch (err) {
            setAvatarError(`Upload failed: ${getErrorMessage(err)}`);
        } finally {
            setIsUploading(false);
            if(fileInputRef.current) {
                fileInputRef.current.value = "";
            }
        }
    };

    const handleRemoveClick = async () => {
        if (!window.confirm("Are you sure you want to remove your profile picture?")) return;
        setIsUploading(true);
        setAvatarError(null);
        try {
            await removeUserAvatar();
        } catch (err) {
            setAvatarError(`Failed to remove avatar: ${getErrorMessage(err)}`);
        } finally {
            setIsUploading(false);
        }
    };

    const handleClearCache = () => {
        if (window.confirm("This will clear all local data (login session, theme, tutorial status) and reload the application. You will need to log in again. Continue?")) {
            localStorage.clear();
            sessionStorage.clear();
            window.location.reload();
        }
    };

    if (!user) {
        return <p>Loading user settings...</p>;
    }

    return (
        <div className="max-w-4xl mx-auto w-full space-y-8 animate-[fade-in-up_0.5s_ease-out] pb-12">
            <style>{`
                @keyframes fade-in-up {
                    from { opacity: 0; transform: translateY(20px); }
                    to { opacity: 1; transform: translateY(0); }
                }
            `}</style>

            <div className="bg-white dark:bg-gray-800 p-8 rounded-2xl shadow-xl border border-primary-200 dark:border-gray-700">
                <h2 className="text-2xl font-bold text-primary-700 dark:text-gray-100 mb-6">Profile Picture</h2>
                <div className="flex flex-col sm:flex-row items-center gap-6">
                    {user.avatar_url ? (
                        <img src={user.avatar_url} alt="Profile" className="w-24 h-24 rounded-full object-cover" />
                    ) : (
                        <ProfileAvatar className="w-24 h-24" />
                    )}
                    <div className="flex-grow w-full sm:w-auto">
                        <div className="flex items-center gap-3">
                            <input
                                type="file"
                                ref={fileInputRef}
                                onChange={handleFileChange}
                                accept="image/png, image/jpeg"
                                className="hidden"
                                id="avatar-upload"
                                disabled={isUploading}
                            />
                            <button
                                onClick={() => fileInputRef.current?.click()}
                                disabled={isUploading}
                                className="font-semibold bg-primary-100 dark:bg-gray-700 text-primary-600 dark:text-gray-300 rounded-md py-2 px-4 transition-colors hover:bg-primary-200 dark:hover:bg-gray-600 disabled:opacity-50"
                            >
                                {isUploading ? 'Processing...' : 'Upload Picture'}
                            </button>
                            {user.avatar_url && (
                                <button
                                    onClick={handleRemoveClick}
                                    disabled={isUploading}
                                    className="font-semibold text-sm text-red-600 dark:text-red-400 hover:text-red-800 dark:hover:text-red-300 disabled:opacity-50"
                                >
                                    Remove
                                </button>
                            )}
                        </div>
                         {avatarError && <p className="text-red-500 text-sm mt-2">{avatarError}</p>}
                         <p className="text-xs text-primary-500 dark:text-gray-400 mt-2">Recommended: Square image under 2MB.</p>
                    </div>
                </div>
            </div>

            <div className="bg-white dark:bg-gray-800 p-8 rounded-2xl shadow-xl border border-primary-200 dark:border-gray-700">
                <h2 className="text-2xl font-bold text-primary-700 dark:text-gray-100 mb-6">Appearance</h2>
                <div className="flex items-center justify-between">
                    <p className="text-primary-600 dark:text-gray-300">Theme</p>
                    <div className="flex items-center gap-2 p-1 rounded-full bg-primary-100 dark:bg-gray-700">
                        <button onClick={() => handleThemeChange(ThemePreference.LIGHT)} className={`p-2 rounded-full transition-colors ${effectiveTheme === 'light' ? 'bg-white shadow' : 'hover:bg-white/50'}`}>
                            <SunIcon className="w-6 h-6 text-yellow-500" />
                        </button>
                        <button onClick={() => handleThemeChange(ThemePreference.DARK)} className={`p-2 rounded-full transition-colors ${effectiveTheme === 'dark' ? 'bg-gray-600 shadow' : 'hover:bg-gray-600/50'}`}>
                            <MoonIcon className="w-6 h-6 text-blue-300" />
                        </button>
                    </div>
                </div>
            </div>

            <div className="bg-white dark:bg-gray-800 p-8 rounded-2xl shadow-xl border border-primary-200 dark:border-gray-700">
                <h2 className="text-2xl font-bold text-primary-700 dark:text-gray-100 mb-6">Edit Profile</h2>
                <form onSubmit={handleProfileSubmit} className="space-y-6">
                    <div>
                        <label htmlFor="full-name" className="block text-sm font-medium text-primary-600 dark:text-gray-300 mb-2">Full Name</label>
                        <input
                            id="full-name"
                            type="text"
                            value={fullName}
                            onChange={(e) => setFullName(e.target.value)}
                            className="w-full bg-primary-100 dark:bg-gray-700 border border-primary-300 dark:border-gray-600 rounded-md px-4 py-2 text-primary-700 dark:text-gray-200 focus:ring-2 focus:ring-primary-500 focus:outline-none"
                            required
                        />
                    </div>
                    {user.role === UserRole.STUDENT && (
                        <div>
                            <label htmlFor="course" className="block text-sm font-medium text-primary-600 dark:text-gray-300 mb-2">Course</label>
                            <input
                                id="course"
                                type="text"
                                value={course}
                                onChange={(e) => setCourse(e.target.value)}
                                placeholder="e.g. Computer Science"
                                className="w-full bg-primary-100 dark:bg-gray-700 border border-primary-300 dark:border-gray-600 rounded-md px-4 py-2 text-primary-700 dark:text-gray-200 focus:ring-2 focus:ring-primary-500 focus:outline-none"
                            />
                        </div>
                    )}
                     {saveError && <div className="bg-red-100 border border-red-300 text-red-700 px-4 py-3 rounded-lg" role="alert">{saveError}</div>}
                     {saveSuccess && <div className="bg-green-100 border border-green-300 text-green-700 px-4 py-3 rounded-lg" role="alert">{saveSuccess}</div>}

                    <div className="flex justify-end">
                         <button type="submit" disabled={isSaving || (fullName === user.full_name && course === (user.course || ''))} className="text-lg font-bold bg-gradient-to-r from-primary-400 to-primary-600 text-white rounded-lg py-2 px-6 transition-all hover:from-primary-500 hover:to-primary-700 disabled:opacity-50 disabled:cursor-not-allowed">
                            {isSaving ? 'Saving...' : 'Save Changes'}
                        </button>
                    </div>
                </form>
            </div>

            {/* Application Reset Section (Danger Zone) */}
            <div className="bg-white dark:bg-gray-800 p-8 rounded-2xl shadow-xl border border-red-200 dark:border-red-900/50">
                <h2 className="text-2xl font-bold text-red-600 dark:text-red-400 mb-4">Danger Zone</h2>
                <p className="text-primary-600 dark:text-gray-300 mb-6">
                    Encountering persistent issues, stuck loading screens, or weird behavior? Resetting the application will clear your local session and cached data. You will be logged out.
                </p>
                <button 
                    onClick={handleClearCache}
                    className="flex items-center justify-center gap-2 font-bold bg-red-50 dark:bg-red-900/20 text-red-600 dark:text-red-400 border-2 border-red-100 dark:border-red-900/50 rounded-lg py-3 px-6 hover:bg-red-100 dark:hover:bg-red-900/40 transition-colors w-full sm:w-auto"
                >
                    <TrashIcon className="w-5 h-5" />
                    Clear Cache & Reset Application
                </button>
            </div>
        </div>
    );
};

export default SettingsPage;

